let latestId = 0;

async function onSearchInput(query: string): Promise<void> {
  const requestId = ++latestId;
  if (requestId !== latestId) {
    return;
  }
  const suggestions = await searchProducts(query, new AbortController().signal);
  renderSuggestions(suggestions);
}

export function SearchBox() {
  const [input, setInput] = useState('');
  const debouncedSearch = debounce(sendSearch, 300);
  return (
    <input
      aria-label="Search products"
      value={input}
      onChange={(event) => {
        setInput(event.target.value);
        debouncedSearch(event.target.value);
      }}
    />
  );
}
